query GetDashboardSummary {
  dashboardSummary {
    netWorth
    netWorthChange
    monthlyIncome
    monthlyExpenses
    cashFlow
    spendingByCategory {
      categoryId
      categoryName
      amount
      percentage
      color
      __typename
    }
    recentTransactions {
      id
      amount
      description
      date
      pending
      account {
        id
        name
        mask
        __typename
      }
      category {
        id
        name
        color
        __typename
      }
      __typename
    }
    accountBalances {
      accountId
      accountName
      accountType
      balance
      __typename
    }
    needsReviewCount
    __typename
  }
}
